":root{color-scheme:dark;--bg:#080e19;--card:#111b2b;--card2:#0c1523;--line:#25344c;--text:#f5f7fb;--muted:#93a2b8;--blue:#4f8cff;--green:#39d69a;--red:#ff6b7d}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text)}body{font:14px/1.45 system-ui,-apple-system,'Segoe UI','PingFang SC',sans-serif;background:radial-gradient(circle at 15% 0,rgba(79,140,255,.16),transparent 30rem),var(--bg)}button,input{font:inherit}button{cursor:pointer}.app{max-width:1160px;margin:auto;padding:22px 18px 40px}.head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.brand{display:flex;align-items:center;gap:10px}.logo{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(145deg,#5b96ff,#2f68df);font-weight:900}.name{font-size:21px;font-weight:800}.sub,.muted{color:var(--muted);font-size:12px}.online{display:flex;align-items:center;gap:7px;border:1px solid rgba(57,214,154,.25);background:rgba(57,214,154,.08);padding:6px 9px;border-radius:999px;color:#a2efd0;font-size:12px}.dot{width:7px;height:7px;border-radius:50%;background:var(--green)}.stats{display:grid;grid-template-columns:1fr .55fr 1.45fr;gap:9px;margin-bottom:13px}.stat{min-width:0;padding:11px 12px;border:1px solid var(--line);border-radius:14px;background:rgba(17,27,43,.78)}.stat b{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px}.grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(290px,.65fr);gap:13px}.stack{display:grid;gap:13px;align-content:start}.card{border:1px solid var(--line);border-radius:18px;background:linear-gradient(180deg,#121d2e,#0e1726);overflow:hidden;box-shadow:0 16px 45px #0004}.ct{padding:14px 15px 0;font-size:15px;font-weight:750}.cd{padding:2px 15px 0;color:var(--muted);font-size:11px}.cb{padding:12px 15px 15px}.drop{min-height:135px;border:1.5px dashed #405270;border-radius:15px;display:grid;place-items:center;text-align:center;padding:18px;background:#0b1422;transition:.18s}.drop.drag{border-color:#6d9fff;background:rgba(79,140,255,.09)}.up{width:38px;height:38px;margin:0 auto 7px;border-radius:12px;background:#172641;display:grid;place-items:center;color:#9abbff;font-size:20px}.drop small{display:block;color:var(--muted);margin-top:4px}.sel{display:flex;justify-content:space-between;gap:8px;margin-top:9px;padding:9px 10px;border-radius:11px;background:#0b1422;border:1px solid #202e44}.selName{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:650}.actions,.fa{display:flex;gap:7px;flex-wrap:wrap}.actions{margin-top:9px}.btn{border:1px solid #34445e;background:#1a273b;color:#eef3fa;border-radius:10px;padding:8px 11px;font-weight:650}.btn.primary{background:linear-gradient(180deg,#5595ff,#3472e7);border-color:#639cff}.btn.danger{color:#ffc0c8;background:rgba(255,107,125,.08);border-color:rgba(255,107,125,.28)}.btn.sm{padding:6px 9px;font-size:12px}.progressBox{display:none;margin-top:10px}.progressBox.show{display:block}.progress{height:7px;border-radius:99px;background:#1c293d;overflow:hidden}.bar{height:100%;width:0;background:linear-gradient(90deg,#4f8cff,#66d6ff)}.ptext{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;margin-top:5px}.files{display:grid;gap:8px}.empty{padding:20px;text-align:center;border:1px dashed #2b3a52;border-radius:13px;color:var(--muted)}.file{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:11px;border-radius:13px;background:#0b1422;border:1px solid #1e2d43}.fn{font-weight:680;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fm{font-size:11px;color:var(--muted);margin-top:3px}.badge{display:inline-block;margin-left:5px;padding:1px 6px;border:1px solid #34445e;border-radius:99px;font-size:10px}.badge.ok{color:#9cecca;border-color:rgba(57,214,154,.25);background:rgba(57,214,154,.07)}.now{padding:12px;border:1px solid #2a3c57;border-radius:14px;background:linear-gradient(135deg,rgba(79,140,255,.10),rgba(57,214,154,.04));margin-bottom:8px}.nt{font-size:17px;font-weight:780;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ns{font-size:12px;color:#b7c4d5;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.state{font-size:11px;color:var(--muted);margin-top:7px}.switch{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0;border-top:1px solid rgba(37,52,76,.7)}.switch:first-child{border-top:0}.swTitle{font-weight:670}.toggle{position:relative;width:42px;height:24px;flex:none}.toggle input{opacity:0}.track{position:absolute;inset:0;border-radius:99px;background:#2b394f;border:1px solid #41516a}.track:after{content:'';position:absolute;width:18px;height:18px;left:2px;top:2px;border-radius:50%;background:#dce5ef;transition:.18s}.toggle input:checked+.track{background:#397af0;border-color:#6099ff}.toggle input:checked+.track:after{transform:translateX(18px);background:#fff}.good{color:#91e8bd}.warn{color:#ffd277}.toast{position:fixed;left:50%;bottom:max(18px,env(safe-area-inset-bottom));transform:translate(-50%,12px);opacity:0;pointer-events:none;background:#eef3fa;color:#101826;padding:9px 12px;border-radius:10px;font-weight:700;box-shadow:0 14px 40px #0008;transition:.18s;z-index:20;max-width:calc(100vw - 24px);text-align:center}.toast.show{opacity:1;transform:translate(-50%,0)}.toast.err{background:#ffd3d9;color:#64131e}@media(max-width:820px){.app{padding:13px 11px calc(28px + env(safe-area-inset-bottom))}.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.stats .stat:last-child{grid-column:1/-1}.card{border-radius:16px}.drop{min-height:116px}.file{grid-template-columns:1fr}.fa{justify-content:flex-start}.actions .btn{flex:1 1 120px}}@media(max-width:430px){.app{padding-left:9px;padding-right:9px}.sub{display:none}.name{font-size:19px}.logo{width:36px;height:36px}.stats{gap:6px}.stat{padding:9px 10px}.ct,.cb,.cd{padding-left:12px;padding-right:12px}.actions{display:grid;grid-template-columns:1fr 1fr}.actions .btn{width:100%}.fa{display:grid;grid-template-columns:repeat(auto-fit,minmax(70px,1fr));width:100%}.fa .btn{width:100%;padding-left:5px;padding-right:5px}.sel{flex-direction:column}.sel .muted{white-space:normal}}"+
"</style></head><body><main class='app'><header class='head'><div class='brand'><div class='logo'>CB</div><div><div class='name'>CarBoxHub</div><div class='sub'>车盒局域网管理中心</div></div></div><div class='online'><span class='dot'></span><span id='online'>连接中</span></div></header>"+
"<section class='stats'><div class='stat'><span class='muted'>设备地址</span><b id='host'>--</b></div><div class='stat'><span class='muted'>版本</span><b id='ver'>--</b></div><div class='stat'><span class='muted'>文件目录</span><b id='storage'>--</b></div></section>"+
"<section class='grid'><div class='stack'><article class='card'><div class='ct'>发送文件</div><div class='cd'>支持 APK 和普通文件，单文件最大 2 GiB</div><div class='cb'><div id='drop' class='drop'><div><div class='up'>↑</div><strong>点击选择文件</strong><small>电脑端也支持拖放</small></div><input id='file' type='file' hidden></div><div class='sel'><span id='selName' class='selName'>尚未选择文件</span><span id='selMeta' class='muted'>选择后即可上传</span></div><div class='actions'><button id='upload' class='btn primary'>上传文件</button><button id='install' class='btn'>上传并安装 APK</button></div><div id='pb' class='progressBox'><div class='progress'><div id='bar' class='bar'></div></div><div class='ptext'><span id='pl'>准备上传</span><span id='pp'>0%</span></div></div></div></article>"+
"<article class='card'><div class='ct'>文件管理</div><div class='cd'><span id='count'>正在读取...</span> · <button id='rf' class='btn sm'>刷新</button></div><div class='cb'><div id='files' class='files'><div class='empty'>正在读取文件...</div></div></div></article></div>"+
"<aside class='stack'><article class='card'><div class='ct'>网易云媒体</div><div class='cd'>车机版网易云播放状态</div><div class='cb'><div class='now'><div id='np' class='nt'>暂无媒体</div><div id='artist' class='ns'>等待网易云播放</div><div id='ms' class='state'>空闲</div></div><div class='switch'><div><div class='swTitle'>媒体投送插件</div><div class='muted'>读取并代理 MediaSession</div></div><label class='toggle'><input id='netease' type='checkbox'><span class='track'></span></label></div></div></article>"+
"<article class='card'><div class='ct'>系统设置</div><div class='cd'>安装与启动选项</div><div class='cb'><div class='switch'><div><div class='swTitle'>Root 静默安装</div><div class='muted'>有 Root 时优先静默安装 APK</div></div><label class='toggle'><input id='rootInstall' type='checkbox'><span class='track'></span></label></div><div class='switch'><div><div class='swTitle'>开机自动启动</div><div class='muted'>车盒启动后恢复服务</div></div><label class='toggle'><input id='autoStart' type='checkbox'><span class='track'></span></label></div><div id='perm' class='muted' style='margin-top:9px'>正在读取安装权限...</div></div></article></aside></section></main><div id='toast' class='toast'></div>"+
"<script>const TOKEN='__TOKEN__',H={'X-CarBox-Token':TOKEN},$=s=>document.querySelector(s);let selected=null,busy=false,tt=0;const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),enc=s=>encodeURIComponent(s).replace(/'/g,'%27');function fmt(n){n=+n||0;if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}function toast(m,e=false){const t=$('#toast');t.textContent=m;t.className='toast show'+(e?' err':'');clearTimeout(tt);tt=setTimeout(()=>t.className='toast',2400)}async function api(p,o={}){o.headers=Object.assign({},o.headers||{},H);const r=await fetch(p,o),x=await r.text();let d;try{d=JSON.parse(x)}catch(e){throw Error(x||('HTTP '+r.status))}if(!r.ok||d.ok===false)throw Error(d.message||('HTTP '+r.status));return d}async function status(){try{const s=await api('/api/status');$('#online').textContent='在线';$('#host').textContent=s.ip+':'+s.port;$('#ver').textContent='v'+s.version+(s.rootAvailable?' · ROOT':'');$('#storage').textContent=s.storagePath;$('#rootInstall').checked=!!s.rootInstall;$('#autoStart').checked=!!s.autoStart;$('#perm').innerHTML=s.canRequestPackageInstalls?'<span class=good>APK 安装权限可用</span>':'<span class=warn>请在车盒端允许安装未知应用</span>';const p=(s.plugins||[]).find(x=>x.id==='netease_media');if(p){$('#netease').checked=!!p.enabled;const n=p.state?.nowPlaying||{};$('#np').textContent=n.title||'暂无媒体';$('#artist').textContent=[n.artist,n.album].filter(Boolean).join(' · ')||'等待网易云播放';$('#ms').innerHTML=(n.playing?'<span class=good>播放中</span>':'暂停 / 空闲')+' · '+(p.state?.notificationAccess?'<span class=good>通知权限正常</span>':'<span class=warn>通知权限未授权</span>')}}catch(e){$('#online').textContent='连接失败'}}async function files(){try{const d=await api('/api/files'),a=d.files||[];$('#count').textContent=a.length+' 个文件';$('#files').innerHTML=a.length?a.map(f=>{const apk=f.apk&&f.apk.valid,meta=[fmt(f.size)];if(apk){meta.push(esc(f.apk.packageName));if(f.apk.versionName)meta.push('v'+esc(f.apk.versionName))}return `<div class=file><div><div class=fn>${esc(f.name)}</div><div class=fm>${meta.join(' · ')}${apk?'<span class=badge>APK</span>':''}${apk&&f.apk.selfUpdate?'<span class=\"badge ok\">CarBoxHub 更新</span>':''}</div></div><div class=fa>${apk?`<button class=\"btn sm\" onclick=\"installFile('${enc(f.name)}')\">安装</button>`:''}<button class=\"btn sm\" onclick=\"downloadFile('${enc(f.name)}')\">下载</button><button class=\"btn danger sm\" onclick=\"delFile('${enc(f.name)}')\">删除</button></div></div>`}).join(''):'<div class=empty>还没有上传文件</div>'}catch(e){$('#files').innerHTML='<div class=empty>读取失败：'+esc(e.message)+'</div>'}}function choose(f){selected=f;$('#selName').textContent=f?f.name:'尚未选择文件';$('#selMeta').textContent=f?fmt(f.size)+(f.name.toLowerCase().endsWith('.apk')?' · APK':''):'选择后即可上传';$('#pb').classList.remove('show')}$('#drop').onclick=()=>$('#file').click();$('#file').onchange=e=>choose(e.target.files[0]);['dragenter','dragover'].forEach(n=>$('#drop').addEventListener(n,e=>{e.preventDefault();$('#drop').classList.add('drag')}));['dragleave','drop'].forEach(n=>$('#drop').addEventListener(n,e=>{e.preventDefault();$('#drop').classList.remove('drag')}));$('#drop').addEventListener('drop',e=>choose(e.dataTransfer.files[0]));function upload(ins){if(busy)return;if(!selected)return toast('请先选择文件',true);if(ins&&!selected.name.toLowerCase().endsWith('.apk'))return toast('上传并安装只支持 APK',true);busy=true;$('#pb').classList.add('show');$('#bar').style.width='0';$('#pl').textContent='正在上传 '+selected.name;$('#pp').textContent='0%';const x=new XMLHttpRequest();x.open('POST','/api/upload?filename='+encodeURIComponent(selected.name)+'&install='+(ins?1:0));x.setRequestHeader('X-CarBox-Token',TOKEN);x.upload.onprogress=e=>{if(e.lengthComputable){const p=Math.min(100,e.loaded/e.total*100);$('#bar').style.width=p+'%';$('#pp').textContent=p.toFixed(0)+'%'}};x.onload=()=>{busy=false;if(x.status>=400)return toast('上传失败',true);$('#bar').style.width='100%';$('#pp').textContent='100%';$('#pl').textContent='上传完成';toast(ins?'上传完成，已发起安装':'上传完成');files();status()};x.onerror=()=>{busy=false;toast('上传失败，请检查网络',true)};x.send(selected)}$('#upload').onclick=()=>upload(false);$('#install').onclick=()=>upload(true);$('#rf').onclick=files;async function installFile(n){try{const d=await api('/api/install?name='+n,{method:'POST'});toast(d.message||'已发起安装');status()}catch(e){toast(e.message,true)}}async function delFile(n){if(!confirm('确定删除这个文件？'))return;try{await api('/api/delete?name='+n,{method:'POST'});toast('已删除');files()}catch(e){toast(e.message,true)}}function downloadFile(n){location.href='/api/download?token='+encodeURIComponent(TOKEN)+'&name='+n}$('#netease').onchange=async e=>{try{await api('/api/plugin?id=netease_media&enabled='+(e.target.checked?1:0),{method:'POST'});toast('设置已保存');status()}catch(x){toast(x.message,true);status()}};$('#rootInstall').onchange=async e=>{try{await api('/api/config?rootInstall='+(e.target.checked?1:0),{method:'POST'});toast('设置已保存');status()}catch(x){toast(x.message,true);status()}};$('#autoStart').onchange=async e=>{try{await api('/api/config?autoStart='+(e.target.checked?1:0),{method:'POST'});toast('设置已保存');status()}catch(x){toast(x.message,true);status()}};status();files();setInterval(status,4000);setInterval(files,12000)</script></body></html>";
